mapper.update:
UPDATE wallet_topups
SET topup_status = 'COMPLETED', transfer_id = #{transferId},
    provider_status = #{providerStatus}, completed_at = #{completedAt}
WHERE topup_id = #{topupId}

mapper.select:
SELECT
    topup_id, topup_status, source_amount, source_currency_code,
    exchange_rate_krw_per_unit, krw_amount, quoted_at, completed_at, created_at
FROM wallet_topups
WHERE wallet_id = #{walletId}
    AND deleted_at IS NULL

        AND topup_id < #{cursor}

ORDER BY topup_id DESC
LIMIT #{limit}
